    function log(message) {
      const logArea = document.getElementById('logArea');
      const time = new Date().toLocaleTimeString();
      const logItem = document.createElement('div');
      logItem.className = 'log-item';
      logItem.textContent = `[${time}] ${message}`;
      logArea.appendChild(logItem);
      logArea.scrollTop = logArea.scrollHeight;
    }
    function clearLog() {
      document.getElementById('logArea').innerHTML = '日志已清空';
    }
    // 1. 内联绑定（在 HTML 中已定义）
    function handleInlineClick() {
      log('内联绑定：按钮被点击（HTML onclick 属性）');
    }
    // 2. DOM 属性绑定
    const propertyBtn1 = document.getElementById('propertyBtn1');
    propertyBtn1.onclick = function() {
      log('属性绑定1：第一个处理函数');
    };
    const propertyBtn2 = document.getElementById('propertyBtn2');
    propertyBtn2.onclick = function() {
      log('属性绑定2：第一个处理函数（会被覆盖）');
    };
    // 重复绑定会覆盖
    propertyBtn2.onclick = function() {
      log('属性绑定2：第二个处理函数（覆盖了第一个）');
    };
    // 3. addEventListener（推荐）
    const listenerBtn = document.getElementById('listenerBtn');
    function handler1() {
      log('addEventListener：处理函数1');
    }
    function handler2() {
      log('addEventListener：处理函数2（不会覆盖）');
    }
    listenerBtn.addEventListener('click', handler1);
    listenerBtn.addEventListener('click', handler2);
    listenerBtn.addEventListener('click', function() {
      log('addEventListener：处理函数3（匿名函数，无法移除）');
    });
    // 移除事件监听
    let handler2Removed = false;
document.getElementById('removeListenerBtn').addEventListener('click', function() {
      if (!handler2Removed) {
        listenerBtn.removeEventListener('click', handler2);
        log('已移除 handler2，再次点击按钮将不再触发 handler2');
        handler2Removed = true;
      } else {
        log('handler2 已被移除，无法再次移除');
      }
    });
    // 初始化日志
    log('页面加载完成，可以开始测试了！');
  


addEventListener
方法（推荐）
通过 DOM 节点的 addEventListener
方法绑定事件，支持绑定多个处理函数，是大伙开发的首选方式。
语法：
element.addEventListener(eventType, handler, useCapture);

eventType：事件类型字符串（如
'click'、'input'，不带 on
前缀）。
handler：事件触发时执行的函数。
useCapture：布尔值（可选，默认
false），表示是否在 “捕获阶段” 触发事件（详见 “事件流”
部分）。

&lt;button id=&quot;btn&quot;&gt;点击我&lt;/button&gt;&lt;script&gt;  const btn = document.getElementById(&#x27;btn&#x27;);    // 绑定第一个处理函数  btn.addEventListener(&#x27;click&#x27;, function() &#123;    console.log(&#x27;点击事件1&#x27;);  &#125;);    // 绑定第二个处理函数（不会覆盖，会依次执行）  btn.addEventListener(&#x27;click&#x27;, function() &#123;    console.log(&#x27;点击事件2&#x27;);  &#125;);&lt;/script&gt;
点击按钮后，控制台会依次输出 点击事件1 和
点击事件2。
Java 中的 swing 也是这样为按钮绑定事件的
他也能移除事件，通过 removeEventListener
移除已绑定的事件（需传入与绑定相同的事件类型和函数）：
function handleClick() &#123;  console.log(&#x27;可移除的事件&#x27;);&#125;// 绑定btn.addEventListener(&#x27;click&#x27;, handleClick);// 移除btn.removeEventListener(&#x27;click&#x27;, handleClick);
事件对象
当事件触发时，浏览器会自动创建一个事件对象（Event
Object），包含事件的详细信息（如触发位置、按键信息等），它会作为参数传递给事件处理函数。
常用属性和方法：







属性 / 方法
说明




target
事件的实际触发节点（事件源）。


currentTarget
绑定事件处理函数的节点（当前处理事件的节点，通常与 this
一致）。


type
事件类型（如 'click'、'input'）。


clientX/clientY
鼠标触发事件时，相对于浏览器可视区域的坐标。


key
键盘事件中，按下的按键值（如
'Enter'、'a'）。


preventDefault()
阻止事件的默认行为（如阻止链接跳转、表单提交）。


stopPropagation()
阻止事件冒泡（详见 “事件流”）。



&lt;a href=&quot;https://example.com&quot; id=&quot;link&quot;&gt;链接&lt;/a&gt;&lt;script&gt;  const link = document.getElementById(&#x27;link&#x27;);    link.addEventListener(&#x27;click&#x27;, function(event) &#123;    // event 是事件对象    console.log(&#x27;事件类型：&#x27;, event.type); // &#x27;click&#x27;    console.log(&#x27;触发节点：&#x27;, event.target); // &lt;a&gt; 元素    console.log(&#x27;当前处理节点：&#x27;, event.currentTarget); // &lt;a&gt; 元素（与 this 一致）        // 阻止链接默认跳转行为    event.preventDefault();  &#125;);&lt;/script&gt;
事件流
事件流就是事件传播机制
当一个事件触发时，会在 DOM
树中按照特定顺序传播，这个过程称为事件流。DOM
事件流分为 3 个阶段：

捕获阶段（Capture Phase）：
事件从最顶层的节点（document）向下传播到事件源的父节点（不包括事件源本身）。
目标阶段（Target Phase）：
事件到达实际触发事件的节点（事件源）。
冒泡阶段（Bubbling Phase）：
事件从事件源向上传播回最顶层的节点（document）。

&lt;div id=&quot;grandparent&quot; style=&quot;padding: 50px; background: red;&quot;&gt;  &lt;div id=&quot;parent&quot; style=&quot;padding: 50px; background: green;&quot;&gt;    &lt;div id=&quot;child&quot; style=&quot;width: 50px; height: 50px; background: blue;&quot;&gt;&lt;/div&gt;  &lt;/div&gt;&lt;/div&gt;&lt;script&gt;  const grandparent = document.getElementById(&#x27;grandparent&#x27;);  const parent = document.getElementById(&#x27;parent&#x27;);  const child = document.getElementById(&#x27;child&#x27;);    // 捕获阶段触发（useCapture: true）  grandparent.addEventListener(&#x27;click&#x27;, () =&gt; console.log(&#x27;爷爷捕获&#x27;), true);  parent.addEventListener(&#x27;click&#x27;, () =&gt; console.log(&#x27;爸爸捕获&#x27;), true);  child.addEventListener(&#x27;click&#x27;, () =&gt; console.log(&#x27;儿子捕获&#x27;), true);    // 冒泡阶段触发（useCapture: false，默认）  grandparent.addEventListener(&#x27;click&#x27;, () =&gt; console.log(&#x27;爷爷冒泡&#x27;), false);  parent.addEventListener(&#x27;click&#x27;, () =&gt; console.log(&#x27;爸爸冒泡&#x27;), false);  child.addEventListener(&#x27;click&#x27;, () =&gt; console.log(&#x27;儿子冒泡&#x27;), false);&lt;/script&gt;
当我们点击蓝色的 child 节点，输出顺序为：
爷爷捕获 → 爸爸捕获 → 儿子捕获 → 儿子冒泡 → 爸爸冒泡 → 爷爷冒泡
可通过 event.stopPropagation()
阻止事件冒泡（避免父节点处理事件）。
