    let stopPropagationEnabled = false;
    function log(message, phase) {
      const logArea = document.getElementById('logArea');
      const time = new Date().toLocaleTimeString();
      const logItem = document.createElement('div');
      logItem.className = 'log-item log-' + phase;
      logItem.textContent = `[${time}] ${message}`;
      logArea.appendChild(logItem);
      logArea.scrollTop = logArea.scrollHeight;
    }
    function clearLog() {
      document.getElementById('logArea').innerHTML = '日志已清空，点击蓝色方块继续测试...';
    }
    function toggleStopPropagation() {
      stopPropagationEnabled = !stopPropagationEnabled;
      const btn = document.getElementById('stopBtn');
      const status = document.getElementById('stopStatus');
      if (stopPropagationEnabled) {
        btn.textContent = '禁用 stopPropagation()';
        status.textContent = '已启用：点击 child 时会阻止冒泡';
        status.style.color = '#f44336';
      } else {
        btn.textContent = '启用 stopPropagation()';
        status.textContent = '已禁用：事件正常冒泡';
        status.style.color = '#4CAF50';
      }
    }
    const grandparent = document.getElementById('grandparent');
    const parent = document.getElementById('parent');
    const child = document.getElementById('child');
    // 捕获阶段（useCapture: true）
    grandparent.addEventListener('click', function(e) {
      grandparent.classList.add('active');
      log('爷爷节点 - 捕获阶段', 'capture');
      setTimeout(() => grandparent.classList.remove('active'), 300);
    }, true);
    parent.addEventListener('click', function(e) {
      parent.classList.add('active');
      log('父节点 - 捕获阶段', 'capture');
      setTimeout(() => parent.classList.remove('active'), 300);
    }, true);
    child.addEventListener('click', function(e) {
      child.classList.add('active');
      log('子节点 - 捕获阶段', 'capture');
      setTimeout(() => child.classList.remove('active'), 300);
    }, true);
    // 目标阶段（在目标节点上，捕获和冒泡都会触发）
    child.addEventListener('click', function(e) {
      log('子节点 - 目标阶段（事件到达目标）', 'target');
      if (stopPropagationEnabled) {
        e.stopPropagation();
        log('已调用 stopPropagation()，阻止事件继续传播', 'target');
      }
    }, false);
    // 冒泡阶段（useCapture: false，默认）
    child.addEventListener('click', function(e) {
      log('子节点 - 冒泡阶段', 'bubble');
    }, false);
    parent.addEventListener('click', function(e) {
      parent.classList.add('active');
      log('父节点 - 冒泡阶段', 'bubble');
      setTimeout(() => parent.classList.remove('active'), 300);
    }, false);
    grandparent.addEventListener('click', function(e) {
      grandparent.classList.add('active');
      log('爷爷节点 - 冒泡阶段', 'bubble');
      setTimeout(() => grandparent.classList.remove('active'), 300);
    }, false);
  


